BASE = dict(wmd_Atridox=WMD_MEAN["SRP+Atridox"], wmd_Periochip=WMD_MEAN["SRP+Periochip"],
            wmd_Arestin=WMD_MEAN["SRP+Arestin"], hm_base=0.0, cost_mult=1.0, recur=1.0, wtp=WTP0)
